start=(11,1); goal=(14,16)
print('eligible',len(places),'start?',start in places,'goal?',goal in places)
def comp(start, places):
 q=collections.deque([start]); seen={start}
 while q:
  r,c=q.popleft()
  for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if p in places and p not in seen: seen.add(p);q.append(p)
 return seen
S=comp(start,places) if start in places else set()
print('reachable',len(S),'goal in?',goal in S)
print('reachable bounding', (min(r for r,c in S), max(r for r,c in S), min(c for r,c in S), max(c for r,c in S)))
print('reach rows:')
for r in range(A.shape[0]-k+1):
